# experimental/nastran_rect_k_synth.jl
#
# Opt-in SOL105 CQUAD4 rectangular elastic-stiffness synthesis.
#
# The coefficient law below was reconstructed from private Nastran MATPRN KGG
# flat one-element PCOMP rectangle matrices.  It is a material/geometry law:
# every coefficient is linear in the laminate/resultant stiffness descriptors
# (Cm, Cb, Cs) multiplied by q^3, q^2, q=Lx/Ly, 1, 1/q,
# 1/q^2, and 1/q^3.
#
# This is intentionally kept behind JFEM_SOL105_K_RECT_SYNTH while it is
# validated on larger meshes.  It does not depend on case names, PIDs/EIDs,
# groups, solver output folders, or internal stress-state selectors.
const _NAS_RECT_K_FEATURES = (
    :Cm11,
    :Cm22,
    :Cm12,
    :Cm16,
    :Cm26,
    :Cm66,
    :Cb11,
    :Cb22,
    :Cb12,
    :Cb16,
    :Cb26,
    :Cb66,
    :Cs11,
    :Cs22,
    :Cs12,
)

