@inline function _rect_k_edge_lengths(coords::AbstractMatrix)
    l12 = hypot(coords[2, 1] - coords[1, 1], coords[2, 2] - coords[1, 2])
    l43 = hypot(coords[3, 1] - coords[4, 1], coords[3, 2] - coords[4, 2])
    l23 = hypot(coords[3, 1] - coords[2, 1], coords[3, 2] - coords[2, 2])
    l14 = hypot(coords[4, 1] - coords[1, 1], coords[4, 2] - coords[1, 2])
    return 0.5 * (l12 + l43), 0.5 * (l23 + l14)
end

@inline function _rect_k_corner_index(x::Float64, y::Float64, cx::Float64, cy::Float64)
    if x <= cx
        return y <= cy ? 1 : 3
    else
        return y <= cy ? 2 : 4
    end
end

function _rect_k_basis_index_by_local_node(coords::AbstractMatrix)
    xmin = minimum(@view coords[:, 1])
    xmax = maximum(@view coords[:, 1])
    ymin = minimum(@view coords[:, 2])
    ymax = maximum(@view coords[:, 2])
    cx = 0.5 * (xmin + xmax)
    cy = 0.5 * (ymin + ymax)
    return ntuple(i -> _rect_k_corner_index(
            Float64(coords[i, 1]), Float64(coords[i, 2]), cx, cy,
        ), 4)
end

function _rect_k_feature_row(q::Float64, Cm::AbstractMatrix, Cb::AbstractMatrix, Cs::AbstractMatrix)
    invq = inv(q)
    feature_values = (
        Float64(Cm[1, 1]), Float64(Cm[2, 2]), Float64(Cm[1, 2]),
        Float64(Cm[1, 3]), Float64(Cm[2, 3]), Float64(Cm[3, 3]),
        Float64(Cb[1, 1]), Float64(Cb[2, 2]), Float64(Cb[1, 2]),
        Float64(Cb[1, 3]), Float64(Cb[2, 3]), Float64(Cb[3, 3]),
        Float64(Cs[1, 1]), Float64(Cs[2, 2]), Float64(Cs[1, 2]),
    )
    row = Vector{Float64}(undef, length(feature_values) * 7)
    k = 1
    @inbounds for val in feature_values
        row[k] = val * q^3
        row[k + 1] = val * q^2
        row[k + 2] = val * q
        row[k + 3] = val
        row[k + 4] = val * invq
        row[k + 5] = val * invq^2
        row[k + 6] = val * invq^3
        k += 7
    end
    return row
end

function _rect_k_corner_order_matrix(q::Float64, Cm::AbstractMatrix, Cb::AbstractMatrix, Cs::AbstractMatrix)
    row = _rect_k_feature_row(q, Cm, Cb, Cs)
    K = zeros(24, 24)
    @inbounds for (i, j, coeffs) in _NAS_RECT_K_COEFFS
        v = 0.0
        for k in eachindex(coeffs)
            v += row[k] * coeffs[k]
        end
        K[i, j] = v
        i == j || (K[j, i] = v)
    end
    return K
end

function stiffness_quad4_nastran_rect_synth(coords::AbstractMatrix,
                                            Cm::AbstractMatrix,
                                            Cb::AbstractMatrix,
                                            Cs::AbstractMatrix)
    lx, ly = _rect_k_edge_lengths(coords)
    lx > 1e-30 && ly > 1e-30 || return zeros(24, 24)
    q = lx / ly
    Kcorner = _rect_k_corner_order_matrix(q, Cm, Cb, Cs)
    Klocal = zeros(24, 24)
    basis_by_local = _rect_k_basis_index_by_local_node(coords)
    @inbounds for a in 1:24, b in 1:24
        local_node_a = div(a - 1, 6) + 1
        local_node_b = div(b - 1, 6) + 1
        comp_a = mod(a - 1, 6) + 1
        comp_b = mod(b - 1, 6) + 1
        basis_a = (basis_by_local[local_node_a] - 1) * 6 + comp_a
        basis_b = (basis_by_local[local_node_b] - 1) * 6 + comp_b
        Klocal[a, b] = Kcorner[basis_a, basis_b]
    end
    return 0.5 .* (Klocal .+ Klocal')
end
